function renderSuggestions(items){suggestions=items;$('#searchResults').innerHTML='';for(const [index,item]of items.entries()){const b=document.createElement('button');b.type='button';b.role='option';b.dataset.index=index;b.textContent=item.text||item.address;b.onclick=()=>locateAddress(item);$('#searchResults').append(b)}setSearchOpen(items.length>0)}
async function requestSuggestions(query){const serial=++searchSerial;if(query.length<3){renderSuggestions([]);return}try{const center=map.getCenter(),url=new URL('https://geocode.arcgis.com/arcgis/rest/services/World/GeocodeServer/suggest');url.search=new URLSearchParams({text:query,f:'json',maxSuggestions:'6',returnCollections:'false',location:`${center.lng},${center.lat}`});const r=await fetch(url,{signal:AbortSignal.timeout(10000)});if(!r.ok)throw Error();const data=await r.json();if(serial!==searchSerial)return;renderSuggestions(data.suggestions||[])}catch{if(serial===searchSerial)renderSuggestions([])}}
async function locateAddress(item){const query=item.text||item.address||$('#address').value.trim(),serial=++searchSerial;$('#searchBtn').disabled=true;$('#searchResults').textContent='Locating address…';setSearchOpen(true);try{const url=new URL('https://geocode.arcgis.com/arcgis/rest/services/World/GeocodeServer/findAddressCandidates'),params={SingleLine:query,f:'json',maxLocations:item.magicKey?'1':'5',outFields:'Match_addr',forStorage:'false'};if(item.magicKey)params.magicKey=item.magicKey;url.search=new URLSearchParams(params);const r=await fetch(url,{signal:AbortSignal.timeout(15000)});if(!r.ok)throw Error('Address service unavailable');const data=await r.json();if(serial!==searchSerial)return;if(data.error)throw Error(data.error.message);const candidates=data.candidates||[];if(!candidates.length&&!item.candidate)throw Error('No matching address found');if(!item.magicKey&&!item.candidate&&candidates.length>1){renderSuggestions(candidates.map(c=>({text:c.address,candidate:c})));return}const c=item.candidate||candidates[0];setView('map');map.setView([c.location.y,c.location.x],20);state.address=c.address;$('#mapStatus').textContent=c.address;$('#address').value=c.address;renderSuggestions([]);setTool('auto');toast('Address located. Click the building to auto-outline it, or choose Draw plane.')}catch(err){$('#searchResults').textContent=`${err.message}. You can still pan and zoom to the roof.`;setSearchOpen(true)}finally{if(serial===searchSerial)$('#searchBtn').disabled=false}}
$('#address').addEventListener('input',e=>{clearTimeout(suggestTimer);const query=e.target.value.trim();suggestTimer=setTimeout(()=>requestSuggestions(query),250)});$('#address').addEventListener('keydown',e=>{const options=$$('#searchResults button');if(e.key==='ArrowDown'&&options.length){e.preventDefault();options[0].focus()}if(e.key==='Escape')renderSuggestions([])});$('#searchResults').addEventListener('keydown',e=>{const options=$$('#searchResults button'),at=options.indexOf(document.activeElement);if(e.key==='ArrowDown'){e.preventDefault();options[(at+1)%options.length]?.focus()}if(e.key==='ArrowUp'){e.preventDefault();(at<=0?$('#address'):options[at-1]).focus()}if(e.key==='Escape'){renderSuggestions([]);$('#address').focus()}});$('#searchForm').onsubmit=e=>{e.preventDefault();const query=$('#address').value.trim();if(query)locateAddress(suggestions.find(s=>s.text===query)||{text:query})};document.addEventListener('click',e=>{if(!$('#searchForm').contains(e.target)&&!$('#searchResults').contains(e.target))setSearchOpen(false)});
function settingsToUI(){const s=state.settings,standard=[12,16,18,20,32,34,36].includes(s.width);$('#panelWidth').value=standard?String(s.width):'custom';$('#customWidth').value=s.width;$('#customWidthRow').hidden=standard;$('#maxLength').value=s.maxLength;$('#allowance').value=s.allowance;$('#panelColor').value=s.color}
function changeSettings(){const width=$('#panelWidth').value==='custom'?+$('#customWidth').value:+$('#panelWidth').value,max=+$('#maxLength').value,allow=+$('#allowance').value;if(!(width>=1&&width<=120&&max>=1&&max<=200&&allow>=0&&allow<=48))return toast('Check the width, length, and allowance limits.');checkpoint();state.settings={width,maxLength:max,allowance:allow,color:$('#panelColor').value};$('#customWidthRow').hidden=$('#panelWidth').value!=='custom';render()}
for(const id of ['panelWidth','customWidth','maxLength','allowance','panelColor'])$('#'+id).onchange=changeSettings;$('#showPanels').onchange=render;
async function setView(mode){view=mode;$('#map').hidden=mode==='three';$('#three').hidden=mode!=='three';$('#threeTip').hidden=mode!=='three';$('#lock').hidden=mode==='three';for(const [id,m]of [['mapView','map'],['planView','plan'],['threeView','three']])$('#'+id).classList.toggle('active',mode===m);if(mode==='three'){await render3D(true)}else{map.invalidateSize();if(mode==='plan'){if(map.hasLayer(tiles))map.removeLayer(tiles);$('#map').classList.add('plan-mode')}else{if(!map.hasLayer(tiles))tiles.addTo(map);$('#map').classList.remove('plan-mode')}render()}}
$('#mapView').onclick=()=>setView('map');$('#planView').onclick=()=>setView('plan');$('#threeView').onclick=()=>setView('three');
let viewerPromise;async function render3D(reset=false){try{if(!viewerPromise)viewerPromise=import('./roof3d.mjs').then(m=>m.createViewer($('#three')));viewer=await viewerPromise;viewer.update(state,summary,$('#showPanels').checked,reset);if(!state.faces.length)toast('Draw a plane on the aerial map to build a 3D roof.')}catch(e){$('#three').textContent='3D rendering is unavailable in this browser. The Aerial and Plan editors still work.';console.error(e)}}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function save(){const payload={...state,address:$('#address').value,view:{center:map.getCenter(),zoom:map.getZoom()}};download('taylor-roof-project.json',JSON.stringify(payload,null,2),'application/json');$('#saveStatus').textContent='Project file downloaded';toast('Project downloaded with coordinates, edges, pitches, and panel settings.')}
$('#save').onclick=save;$('#open').onclick=()=>$('#fileInput').click();$('#fileInput').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>2e6)throw Error('File too large');const p=JSON.parse(await file.text());if(p.version!==2||!Array.isArray(p.faces)||p.faces.length>100||!Number.isFinite(p.origin?.lat)||!Number.isFinite(p.origin?.lng)||Math.abs(p.origin.lat)>85||Math.abs(p.origin.lng)>180)throw Error('Not a valid roof project');for(const f of p.faces){if(!Array.isArray(f.points)||f.points.length<3||f.points.length>300||f.points.some(x=>!Number.isFinite(x.lat)||!Number.isFinite(x.lng)||Math.abs(x.lat)>85||Math.abs(x.lng)>180)||!validPolygon(f.points.map(x=>project(x,p.origin)))||!(f.pitch>=0&&f.pitch<=24)||!(f.bearing>=0&&f.bearing<=359)||!(f.eave>=0&&f.eave<=200))throw Error('Invalid plane data');f.id=crypto.randomUUID();f.name=String(f.name).slice(0,60);f.type=['Main roof','Dormer','Porch','Garage'].includes(f.type)?f.type:'Main roof';f.edges=f.points.map((_,i)=>Object.hasOwn(colors,f.edges?.[i])?f.edges[i]:'Unlabeled')};const s=p.settings;if(!(s?.width>=1&&s.width<=120&&s.maxLength>=1&&s.maxLength<=200&&s.allowance>=0&&s.allowance<=48)||!/^#[a-f\d]{6}$/i.test(s.color))throw Error('Invalid panel settings');checkpoint();state={version:2,origin:p.origin,faces:p.faces,settings:s,address:String(p.address||'').slice(0,300)};selected=state.faces[0]?.id;$('#address').value=state.address;$('#mapStatus').textContent=state.address||'Loaded roof project';draft=[];settingsToUI();setTool('pan');updateEditor();if(state.faces.length)fit();$('#saveStatus').textContent='Project opened';toast('Project restored.')}catch(err){toast('Could not open project: '+err.message)}finally{e.target.value=''}};
function cutGroups(){const groups=new Map();for(const r of summary.rows)for(const p of r.panels){const key=`${r.face.id}:${p.length}`;if(!groups.has(key))groups.set(key,{name:r.face.name,length:p.length,qty:0,oversize:p.oversize});groups.get(key).qty++}return [...groups.values()]}
function showDialog(title,html){$('#dialogTitle').textContent=title;$('#dialogContent').innerHTML=html;$('#dialog').showModal()}$('#closeDialog').onclick=()=>$('#dialog').close();$('#cutList').onclick=()=>showDialog('Panel cut list',summary.count?`<p>${summary.count} panels · ${state.settings.width}″ effective coverage. Cut lengths include ${state.settings.allowance}″ total end allowance.</p><table><thead><tr><th>Plane</th><th>Length</th><th>Qty</th><th>Check</th></tr></thead><tbody>${cutGroups().map(p=>`<tr><td>${esc(p.name)}</td><td>${feet(p.length)}</td><td>${p.qty}</td><td>${p.oversize?'Exceeds max length':'Within length limit'}</td></tr>`).join('')}</tbody></table><p>Conservative rectangular blanks. Field verification and fabricator review required; no offcut nesting or engineered laps.</p>`:'<p>Draw a roof plane first. Its cut lengths will appear here.</p>');
$('#exportCSV').onclick=()=>{if(!summary.count)return toast('Draw a plane before exporting cuts.');const csvCell=s=>'"'+String(s).replace(/^[=+@-]/,"'").replace(/"/g,'""')+'"';const csv=['Plane,Coverage width (in),Length (ft),Quantity,Status',...cutGroups().map(p=>[csvCell(p.name),state.settings.width,p.length.toFixed(4),p.qty,p.oversize?'EXCEEDS MAX LENGTH':'FIELD VERIFY'].join(','))].join('\r\n');download('taylor-panel-cuts.csv',csv,'text/csv');toast('Cut list downloaded.')};
$('#exportPlan').onclick=()=>{if(!state.faces.length)return toast('Draw a roof plane first.');const pts=state.faces.flatMap(f=>f.points.map(p=>project(p,state.origin))),minX=Math.min(...pts.map(p=>p.x)),maxX=Math.max(...pts.map(p=>p.x)),minY=Math.min(...pts.map(p=>p.y)),maxY=Math.max(...pts.map(p=>p.y)),scale=Math.min(800/(maxX-minX),570/(maxY-minY)),xy=p=>({x:100+(p.x-minX)*scale,y:100+(maxY-p.y)*scale}),pair=p=>{const q=xy(p);return `${q.x},${q.y}`};let content='';for(const r of summary.rows){content+=`<polygon points="${r.points.map(pair).join(' ')}" fill="${state.settings.color}" fill-opacity=".4" stroke="#156587" stroke-width="2"/>`;if($('#showPanels').checked)for(const p of r.panels)content+=`<polygon points="${p.polygon.map(pair).join(' ')}" fill="none" stroke="#336f87" stroke-width=".7"/>`;const c=xy({x:r.points.reduce((s,p)=>s+p.x,0)/r.points.length,y:r.points.reduce((s,p)=>s+p.y,0)/r.points.length});content+=`<text x="${c.x}" y="${c.y}" text-anchor="middle" font-size="14">${esc(r.face.name)} · ${r.face.pitch}/12 · ${num(r.surface/FT**2)} ft²</text>`}for(const e of edgeRecords()){const a=xy(project(e.a,state.origin)),b=xy(project(e.b,state.origin));content+=`<text x="${(a.x+b.x)/2}" y="${(a.y+b.y)/2-5}" text-anchor="middle" font-size="12" paint-order="stroke" stroke="white" stroke-width="4" fill="#0b263b">${e.type} ${feet(e.length)}</text>`}const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="1000" height="800" viewBox="0 0 1000 800"><rect width="1000" height="800" fill="#f1f7fa"/><g font-family="Arial" fill="#09273a"><text x="40" y="40" font-size="23">Taylor Metal — Measured roof plan</text><text x="40" y="65" font-size="14">${esc($('#address').value)} · North ↑</text>${content}<text x="40" y="730" font-size="16">Plan: ${num(summary.flat,1)} ft² · Sloped: ${num(summary.surface,1)} ft² · Panels: ${summary.count}</text><text x="40" y="765" font-size="12">Aerial estimate — verify on site. Geography is preserved in the accompanying saved project JSON.</text></g></svg>`;download('taylor-measured-roof.svg',svg,'image/svg+xml');toast('Measured plan downloaded with dimensions.')};
$('#help').onclick=()=>showDialog('Outline a roof, then plan panels','<ol><li><b>Find your roof:</b> start typing an address and choose a suggested match. The imagery is Esri aerial imagery, not Google.</li><li><b>Start an outline:</b> choose Auto-outline and click the building. If no public footprint is available, choose Draw plane and click its corners manually.</li><li><b>Refine:</b> select a plane and drag white corners. Click a small midpoint to add a corner. Right-click a corner to remove it. Undo restores edits.</li><li><b>Label and measure:</b> open Label edges, choose ridge, hip, valley, rake, eave, or flashing, then click the line. Enter field-measured feet and inches in Selected roof line. The second endpoint moves along the line and both corners remain draggable.</li><li><b>Build roof planes:</b> the automatic result is an exterior building footprint. Use Draw plane for the individual roof surfaces whose shared edges become ridges, hips, and valleys.</li><li><b>Set pitch:</b> enter rise per 12 inches and set the downslope direction. The arrow points toward the low edge. Sloped area is calculated independently for every plane.</li><li><b>Plan panels:</b> select effective coverage width, maximum length, and total end allowance. View the layout, 3D roof, and cut list. Overlength panels are flagged, not automatically spliced.</li><li><b>Keep your work:</b> Save project downloads an editable file. Open project restores it. Export plan creates a dimensioned drawing; Export cuts creates a cut list.</li></ol><p>Automatic outlines come from public mapped footprints, not roof-image detection. Coverage and accuracy vary. Check pitch and important dimensions on site.</p>');
render();updateEditor();
